positions = {"A": [1, 0], "B": [0, 0], "C": [1, 1], "D": [2, 1]}
graph = {"A": ["B", "C"], "B": [], "C": ["D"], "D": []}
visited = []
stack = ["A"]
while len(stack) > 0:
    room = stack.pop()
    if room not in visited:
        visited.append(room)
        for neighbor in graph[room]:
            if neighbor not in visited:
                stack.append(neighbor)
say(str(len(visited)))
